import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression

MAX_DRIVERS = 5

def design(feats):
    # Check if any feature shows strong association with outcome
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('copy_number', 'expression'):
            # Use Welch's t-test effect size
            t_stat, _ = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i], equal_var=False)
            effects.append((abs(t_stat), fid))

    # Sort by effect size
    effects.sort(reverse=True)

    # Check for near-duplicates and remove them
    to_remove = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if feats.types[i] == feats.types[j]:
                corr = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
                if abs(corr) >= 0.6:
                    to_remove.add(fid2)

    # Filter out near-duplicates
    filtered_effects = [(eff, fid) for eff, fid in effects if fid not in to_remove]

    # If no strong effects, return empty design
    if len(filtered_effects) < 1:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top features (at most MAX_DRIVERS-1 to leave room for other mechanisms)
    top_features = [fid for _, fid in filtered_effects[:MAX_DRIVERS-1]]

    # For simplicity, just use the top effect sizes as drivers
    drivers = tuple([fid for _, fid in filtered_effects[:MAX_DRIVERS-1]])

    # Return design with drivers and their columns
    return Design(
        drivers=drivers,
        columns=tuple(top_features),
        products=(),
        loadings={fid: 1.0 for fid in top_features}
    )

